//! GPIO
//! General Purpose Input/Output

#![allow(dead_code)]

pub const BASE: u32 = 0x500e0000;

/// BT_SELECT Register
///
/// GPIO bit select register
///
/// Address offset: 0x0000
///
/// ## Fields
///
/// - **BT_SEL** `[31:0]` (RW)
///
///   GPIO bit select register
#[repr(transparent)]
pub struct BtSelect {
    value: crate::common::VolatileCell<u32>,
}

impl core::ops::Deref for BtSelect {
    type Target = crate::common::VolatileCell<u32>;
    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl BtSelect {
    // ======== Field Constants ========

    /// **BT_SEL**
    ///
    /// GPIO bit select register
    ///
    /// Bits `[31:0]`, mask `0xffffffff`
    pub const BT_SEL_OFFSET: u32 = 0;
    pub const BT_SEL_MASK: u32 = 0xffffffff;

    // ======== Field Accessors ========

    /// **BT_SEL** `[31:0]` (RW)
    ///
    /// GPIO bit select register
    #[inline(always)]
    pub fn bt_sel(&self) -> u32 {
        (self.value.read_bits() & Self::BT_SEL_MASK) >> Self::BT_SEL_OFFSET
    }

    /// Write **BT_SEL** `[31:0]` (RW)
    ///
    /// GPIO bit select register
    #[inline(always)]
    pub fn write_bt_sel(&self, value: u32) {
        self.value.modify_bits(|r| {
            (r & !Self::BT_SEL_MASK) | ((value << Self::BT_SEL_OFFSET) & Self::BT_SEL_MASK)
        });
    }
}

